<script setup lang="ts">
import { ref,watch } from 'vue'
import { get } from '../api'
import type { Evidence,GraphEdge,Message,Page } from '../api'
import { filters,selection,exportJson } from '../store'
const props=defineProps<{revision:number;evidenceId:string;focusKey?:number;selectedEdge?:GraphEdge}>()
const emit=defineEmits<{entity:[id:string];evidence:[id:string]}>()
const readerTab=ref('list')
const messages=ref<Page<Message>>(),detail=ref<Evidence>(),page=ref(1),error=ref(''),loading=ref(false),copied=ref(false)
let revision=0,detailRevision=0
async function load(){const request=++revision;loading.value=true;error.value='';try{const data=await get<Page<Message>>('messages',{...filters.value,entity_id:selection.messageIds.length?undefined:filters.value.entity_id,page:page.value,page_size:10,ids:selection.messageIds.join(',')});if(request===revision)messages.value=data}catch(e){if(request===revision)error.value=(e as Error).message}finally{if(request===revision)loading.value=false}}
async function loadDetail(){const request=++detailRevision;detail.value=undefined;error.value='';if(!props.evidenceId)return;try{const data=await get<Evidence>(`evidence/${encodeURIComponent(props.evidenceId)}`);if(request===detailRevision)detail.value=data}catch(e){if(request===detailRevision)error.value=(e as Error).message}}
watch(()=>props.revision,()=>{page.value=1;load()},{immediate:true})
watch([()=>props.evidenceId,()=>props.focusKey],()=>{readerTab.value=props.evidenceId?'detail':'list';loadDetail()},{immediate:true})
watch(()=>selection.messageIds,()=>{page.value=1;load()},{deep:true})
watch(page,load)
function open(id:string){emit('evidence',id)}
async function copy(){try{await navigator.clipboard.writeText(props.evidenceId);copied.value=true;window.setTimeout(()=>copied.value=false,2000)}catch{error.value='无法访问剪贴板，可手动选择节点 ID 复制。'}}
</script>
<template><div class="reader-layout"><div class="reader-tabs"><button :class="{active:readerTab==='list'}" @click="readerTab='list'">通信列表</button><button :class="{active:readerTab==='detail'}" @click="readerTab='detail'">证据详情</button></div><div v-show="readerTab==='list'" class="message-list"><div class="reader-toolbar"><span>原始通信 <b data-testid="message-total">{{messages?.total||0}}</b> 条 <small v-if="selection.messageIds.length">/ 所选连接</small></span><button class="chip" @click="exportJson('mc3-message-page.json',{filters:filters,source:'MC3_release/MC3_graph.json',...messages})">↓ 导出当前页</button></div><div v-if="error" class="error" role="alert">{{error}}</div><div v-if="loading&&!messages" class="empty">正在加载消息…</div><div v-else-if="!messages?.items.length" class="empty">当前筛选没有消息。请调整日期、主体或搜索词。</div><div class="message-scroll scroll"><article v-for="m in messages?.items" :key="m.id" class="message-card" :class="{selected:evidenceId===m.id}" data-testid="message-card"><div class="message-meta"><button class="link mono" @click="open(m.id)">{{m.id}}</button><span>{{m.timestamp}}</span></div><div class="message-direction"><button @click="emit('entity',m.sender)">{{m.sender}}</button><span>→</span><button @click="emit('entity',m.receiver)">{{m.receiver}}</button><span class="badge">直接通信</span></div><p>{{m.content}}</p><div class="message-targets"><span>支撑 {{m.evidence_ids.length}} 个目标</span><button v-for="id in m.evidence_ids.slice(0,3)" :key="id" class="chip" @click="open(id)">{{id}}</button><span v-if="!m.evidence_ids.length">无 evidence_for 连接，原文保留</span><button v-if="m.evidence_ids.length>3" class="link" @click="open(m.id)">查看全部 →</button></div></article></div><div class="pagination"><span>按时间 / ID 稳定排序</span><button :disabled="page===1" @click="page--">←</button><span>{{page}} / {{Math.max(1,Math.ceil((messages?.total||0)/10))}}</span><button :disabled="page*10>=(messages?.total||0)" @click="page++">→</button></div></div>
<aside v-show="readerTab==='detail'" class="detail-pane scroll"><template v-if="selectedEdge"><div class="detail-eyebrow">所选连接</div><p>{{selectedEdge.source}} → {{selectedEdge.target}}</p><span :class="['badge',selectedEdge.is_inferred?'inferred':'']">{{selectedEdge.is_inferred?'文本推断':'直接记录'}}</span> <span class="muted">{{selectedEdge.type}} · {{selectedEdge.weight}} 条</span><hr></template><template v-if="detail"><div class="detail-eyebrow">{{detail.status==='observed'?'原始记录':'文本推断 / 待核查'}}</div><div class="detail-title">{{detail.node.label||detail.node.sub_type}}</div><div class="detail-id mono" data-testid="detail-id">{{detail.node.id}}</div><div v-if="detail.checks?.length" class="source-checks"><p v-for="check in detail.checks" :key="check.code">{{check.text}}</p></div><div class="detail-actions"><button class="chip" @click="copy">{{copied?'已复制':'复制 ID'}}</button><button class="chip" @click="exportJson('mc3-evidence.json',detail)">↓ 导出证据</button></div><p v-if="detail.symmetric" class="symmetry">对称关系：两名实体均指向关系节点，不表示单向联系。</p><div class="detail-participants"><button class="chip" v-for="id in detail.participants" :key="id" @click="emit('entity',id)">{{id}}</button></div><div v-for="m in detail.messages" :key="m.id" class="support-message"><button class="link mono" @click="open(m.id)">{{m.id}}</button><div>{{m.timestamp}} · {{m.sender}} → {{m.receiver}}</div><div v-if="detail.message_checks?.[m.id]?.length" class="message-checks"><div v-for="check in detail.message_checks[m.id]" :key="check.code"><p>{{check.text}}</p><button v-for="id in check.related_ids" :key="id" class="link mono" @click="open(id)">{{id}}</button></div></div><p>{{m.content}}</p></div><div v-if="!detail.messages.length" class="panel-note">该节点没有直接的 evidence_for 支撑消息；可通过原始连接继续检查。</div><div v-if="detail.targets.length"><h4>此通信支撑的目标</h4><button v-for="n in detail.targets" :key="n.id" class="target-link" @click="open(n.id)"><span class="badge inferred">{{n.sub_type}}</span>{{n.id}} →</button></div><details v-if="detail.nearby_exchange?.length" class="nearby-exchange"><summary>同双方附近 24 小时通信（{{detail.nearby_exchange.length}}）</summary><p>按时间排列，最多 6 条，仅供核对请求与回应，不表示因果；此上下文可能超出当前筛选范围。</p><article v-for="row in detail.nearby_exchange" :key="row.id"><button class="link mono" @click="open(row.id)">{{row.id}}</button><small>{{row.timestamp}} · {{row.sender}} → {{row.receiver}}</small><p>{{row.content}}</p></article></details><details><summary>原始节点字段</summary><pre>{{JSON.stringify(detail.node,null,2)}}</pre></details><details><summary>全部原始连接（{{detail.edges.length}}）</summary><div v-for="edge in detail.edges" :key="edge.key" class="raw-edge" :class="{inferred:edge.is_inferred}"><button class="link" @click="open(edge.source)">{{edge.source}}</button><span> → {{edge.type||'结构连接'}} → </span><button class="link" @click="open(edge.target)">{{edge.target}}</button><div>{{edge.is_inferred?'文本推断':'直接记录'}} · {{edge.key}}</div></div></details><details><summary>数据来源</summary><p class="source-path">{{detail.source.member}}<br>ZIP SHA-256：{{detail.source.sha256}}</p></details></template><div v-else class="empty"><span class="detail-icon">⌕</span><p>选择一条通信、图节点或连线<br>检查原文与证据连接</p><button class="chip" @click="open('Event_Communication_1')">打开第一条原始通信 →</button></div></aside></div></template>
<style scoped>
.reader-layout{display:flex;flex-direction:column;flex:1;min-height:0}.reader-tabs{display:flex;gap:18px;padding:0 14px;border-bottom:1px solid var(--selected);flex-shrink:0}.reader-tabs button{border:0;border-bottom:2px solid transparent;border-radius:0;padding:10px 0;background:transparent;color:var(--muted);font-size:12px}.reader-tabs button.active{color:var(--blue);border-bottom-color:var(--blue)}.message-list{display:flex;flex-direction:column;flex:1;min-height:0}.reader-toolbar{padding:10px 14px;display:flex;align-items:center;justify-content:space-between;font-size:12px;color:var(--muted);border-bottom:1px solid var(--selected);gap:6px}.reader-toolbar b{color:var(--blue)}.reader-toolbar small{font-size:12px}.reader-toolbar .chip{font-size:12px}.message-scroll{flex:1;min-height:0}.message-card{padding:14px;border-bottom:1px solid var(--selected)}.message-card.selected{background:var(--surface);box-shadow:inset 3px 0 var(--blue)}.message-meta{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted)}.message-meta .link{font-size:12px}.message-direction{display:flex;gap:5px;align-items:center;flex-wrap:wrap;margin-top:8px;font-size:12px;color:var(--muted)}.message-direction button{background:none;border:0;padding:0;color:var(--ink);font-size:13px;font-weight:600}.message-direction .badge{margin-left:auto;font-size:12px}.message-card p{font-size:14px;line-height:1.85;color:var(--ink);margin:10px 0;overflow-wrap:anywhere}.message-targets{display:flex;gap:5px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--muted)}.message-targets .chip{font-size:12px}.pagination{display:flex;gap:8px;align-items:center;justify-content:flex-end;font-size:12px;padding:10px 14px;color:var(--muted);border-top:1px solid var(--selected);flex-shrink:0}.pagination>span:first-child{margin-right:auto;font-size:12px}.pagination button{padding:3px 7px}.detail-pane{padding:16px;flex:1;min-height:0;background:var(--panel)}.detail-eyebrow{font-size:12px;color:#79629a}.detail-title{font-size:19px;color:var(--ink);margin:8px 0}.detail-id{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.detail-actions,.detail-participants{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.support-message{border-left:2px solid var(--border);padding:6px 10px;margin:16px 0;font-size:12px;line-height:1.8;color:var(--muted)}.support-message .link{font-size:12px}.support-message p{color:var(--ink);font-size:14px;line-height:1.85;margin:8px 0;overflow-wrap:anywhere}.detail-pane details{margin:18px 0;font-size:12px;color:var(--muted)}.detail-pane summary{cursor:pointer}.source-path{overflow-wrap:anywhere;font-size:13px;color:var(--muted);line-height:1.8}.raw-edge{margin:10px 0;border-left:2px solid #6c9f96;padding:5px 8px;font-size:12px}.raw-edge.inferred{border-left:2px dashed #9984b6}.raw-edge div{color:var(--muted)}.detail-icon{font-size:36px;color:var(--muted)}.empty p{font-size:13px}.target-link{display:flex;gap:6px;align-items:center;background:transparent;border:0;margin:10px 0;padding:0;font-size:12px;color:var(--blue);text-align:left;overflow-wrap:anywhere}.detail-pane h4{font-size:13px;font-weight:500}.symmetry{font-size:12px;color:#79629a;line-height:1.8}hr{margin:18px 0}
.source-checks,.message-checks{border-left:3px solid #bb8b3f;background:#fbf5e9;padding:6px 9px;font-size:12px;color:#795a2c;line-height:1.8}.source-checks p,.message-checks p{font-size:12px!important;color:#795a2c!important;margin:4px 0!important}.message-checks button{margin-right:8px}.nearby-exchange article{padding:10px 0;border-top:1px solid var(--selected)}.nearby-exchange small{display:block;margin-top:5px;color:var(--muted)}.nearby-exchange article p{font-size:13px;line-height:1.8}
</style>
